#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeCore: FfiConverter {
    typealias FfiType = UInt64
    typealias SwiftType = Core

    public static func lift(_ handle: UInt64) throws -> Core {
        return Core(unsafeFromHandle: handle)
    }

    public static func lower(_ value: Core) -> UInt64 {
        return value.uniffiCloneHandle()
    }

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> Core {
        let handle: UInt64 = try readInt(&buf)
        return try lift(handle)
    }

    public static func write(_ value: Core, into buf: inout [UInt8]) {
        writeInt(&buf, lower(value))
    }
}


#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public func FfiConverterTypeCore_lift(_ handle: UInt64) throws -> Core {
    return try FfiConverterTypeCore.lift(handle)
}

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public func FfiConverterTypeCore_lower(_ value: Core) -> UInt64 {
    return FfiConverterTypeCore.lower(value)
}






/**
 * An open local shell or SSH shell.
 */
public protocol SessionProtocol: AnyObject, Sendable {
    
    /**
     * Ends the session. Its sink gets no `closed` for it. A persistent SSH
     * session's tmux/screen session stays on the host, detached: see
     * [`Session::disconnect`].
     */
    func close() async throws 
    
    /**
     * Upstream's `ssh_detect_distro`: `ubuntu`, `debian`, `proxmox`, `pbs`…, `linux`
     * when unknown, or `windows`/`routeros` from the SSH banner.
     */
    func detectDistro() async throws  -> String
    
    /**
     * Upstream's `ssh_disconnect`: ends an SSH session after typing `post_command`.
     * With `kill_persistent` it also ends the session's tmux/screen session on the
     * host, unless another client is attached to it (`attached`: this session's
     * own channel still is), and returns whether it did. Its sink gets no `closed`.
     *
     * `reconnecting` has no effect; it stays for callers.
     */
    func disconnect(postCommand: String?, killPersistent: Bool, attached: Bool, reconnecting: Bool) async throws  -> Bool
    
    /**
     * What [`Core::ssh_connect`] reconnects under.
     */
    func id()  -> String
    
    func resize(cols: UInt16, rows: UInt16) async throws 
    
    /**
     * Upstream's `ssh_get_system_info`, as JSON: `pretty_name`, `version_id`,
     * `kernel`, `arch` (empty when the host does not say).
     */
    func systemInfo() async throws  -> String
    
    func write(data: Data) async throws 
    
}
